CREATE TABLE users (id VARCHAR(36) PRIMARY KEY, username VARCHAR(120) UNIQUE NOT NULL, display_name VARCHAR(160) NOT NULL, preferred_language VARCHAR(5) DEFAULT 'en', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE passkeys (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, credential_id TEXT NOT NULL, public_key TEXT NOT NULL, counter INTEGER DEFAULT 0, transports TEXT, device_type VARCHAR(80), backed_up BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_used_at TIMESTAMP NULL);
CREATE TABLE folders (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, name VARCHAR(160) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notes (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, folder_id VARCHAR(36) NULL, title VARCHAR(255) NOT NULL, body TEXT, transcript TEXT, transcription_status VARCHAR(40), summary TEXT, key_points_json JSON, action_items_json JSON, mind_map_json JSON, source VARCHAR(80), meeting_platform VARCHAR(120), meeting_url TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL);
CREATE TABLE recordings (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, note_id VARCHAR(36) NOT NULL, file_path TEXT NOT NULL, mime_type VARCHAR(120), duration_seconds INTEGER DEFAULT 0, size_bytes INTEGER DEFAULT 0, source VARCHAR(80), meeting_platform VARCHAR(120), meeting_url TEXT, started_at TIMESTAMP NULL, ended_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_jobs (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, note_id VARCHAR(36) NOT NULL, type VARCHAR(80), status VARCHAR(40), error TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE extension_pairing_tokens (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, token_hash TEXT NOT NULL, expires_at TIMESTAMP NOT NULL, used_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE extension_sessions (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, token_hash TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_used_at TIMESTAMP NULL, revoked_at TIMESTAMP NULL);
